DROP TABLE IF EXISTS `pp_order`;
CREATE TABLE `pp_order`  (
  `id` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '主键标识',
  `order_no` varchar(90) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '订单编号',
  `order_price` decimal(10, 2) NULL DEFAULT NULL COMMENT '订单价格',
