  `send_status` bit(1) NULL DEFAULT NULL COMMENT '是否发货',
  `user_id` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `created` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated` datetime NULL DEFAULT NULL COMMENT '更新订单时间',
  `updated_by` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新订单人',
  `order_status` int(11) NULL DEFAULT NULL COMMENT '订单状态',
  `order_from` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '订单来源',
  `order_date` datetime NULL DEFAULT NULL COMMENT '提交时间',
  `order_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '订单类型',
  `delivery_method` varchar(25) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '配送方式',
  `tracking_number` varchar(90) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '物流单号',
  `auto_confirm_time` datetime NULL DEFAULT NULL COMMENT '自动确认收货时间',
  `orders_receive_premium` int(11) NULL DEFAULT NULL COMMENT '订单可得优币',
  `event_information` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '活动信息',
  `order_generate_value` int(11) NULL DEFAULT NULL COMMENT '订单可得成长值',
  `consignee` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '收货人',
  `phone` varchar(11) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '手机号码',
  `postal_code` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '邮政编码',
  `address` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '收货地址',
  `freight` decimal(10, 2) NULL DEFAULT NULL COMMENT '运费',
  `coupon` decimal(10, 2) NULL DEFAULT NULL COMMENT '优惠券',
  `deductal` decimal(10, 2) NULL DEFAULT NULL COMMENT '积分抵扣',
  `event_discounts` decimal(10, 2) NULL DEFAULT NULL COMMENT '活动优惠',
  `discount_amount` decimal(10, 2) NULL DEFAULT NULL COMMENT '折扣金额',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '订单表' ROW_FORMAT = DYNAMIC;

